def sum_of_common_divisors(a, b):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def divisors(n):
        divs = set()
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divs.add(i)
                divs.add(n // i)
        return divs

    common_divisors = divisors(gcd(a, b))
    return sum(common_divisors)

# Example usage and test
assert sum_of_common_divisors(10, 15) == 6
```

