def comb_sort(arr):
    def get_next_gap(gap):
        # Shrink gap by a shrink factor of 1.3
        gap = int(gap / 1.3)
        return max(gap, 1)

    n = len(arr)
    gap = n
    swapped = True

    while gap != 1 or swapped:
        gap = get_next_gap(gap)
        swapped = False

        for i in range(n - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True

    return arr

# Example test
assert comb_sort([5, 15, 37, 25, 79]) == [5, 15, 25, 37, 79]
```

